class CircularQueue:
    def __init__(self, k: int) -> None:
        self.slots = [0] * k
        self.head = 0  # the index of the front value
        self.size = 0  # how many values the queue holds

    def enqueue(self, x: int) -> bool:
        if self.is_full():
            return False
        self.slots[(self.head + self.size) % len(self.slots)] = x
        self.size += 1
        return True

    def dequeue(self) -> bool:
        if self.is_empty():
            return False
        self.head = (self.head + 1) % len(self.slots)
        self.size -= 1
        return True

    def front(self) -> int:
        return -1 if self.is_empty() else self.slots[self.head]

    def rear(self) -> int:
        if self.is_empty():
            return -1
        return self.slots[(self.head + self.size - 1) % len(self.slots)]

    def is_empty(self) -> bool:
        return self.size == 0

    def is_full(self) -> bool:
        return self.size == len(self.slots)


