    private final int[] slots;
    private int head = 0; // the index of the front value
    private int size = 0; // how many values the queue holds

    CircularQueue(int k) {
        slots = new int[k];
    }

    boolean enqueue(int x) {
        if (isFull()) {
            return false;
        }
        slots[(head + size) % slots.length] = x;
        size++;
        return true;
